import initSqlJs, { Database } from 'sql.js';
import path from 'path';
import fs from 'fs';

const DB_DIR = path.join(__dirname, '..', '..', 'data');
const DB_PATH = path.join(DB_DIR, 'dealership.db');

let dbInstance: Database | null = null;
let sqlJs: Awaited<ReturnType<typeof initSqlJs>> | null = null;

/**
 * Initialize sql.js and return the module.
 * Caches the wasm module after first load for performance.
 */
async function getSqlJs() {
  if (!sqlJs) {
    sqlJs = await initSqlJs();
  }
  return sqlJs;
}

/**
 * Get (or create) the production SQLite database.
 * Loads from disk if file exists, otherwise creates fresh.
 */
export async function getDatabase(): Promise<Database> {
  if (dbInstance) return dbInstance;

  const SQL = await getSqlJs();

  if (!fs.existsSync(DB_DIR)) {
    fs.mkdirSync(DB_DIR, { recursive: true });
  }

  if (fs.existsSync(DB_PATH)) {
    const fileBuffer = fs.readFileSync(DB_PATH);
    dbInstance = new SQL.Database(fileBuffer);
  } else {
    dbInstance = new SQL.Database();
  }

  initializeSchema(dbInstance);
  return dbInstance;
}

/**
 * Persist the in-memory database to disk.
 * Call this after any write operation.
 */
export function persistDatabase(db: Database): void {
  const data = db.export();
  const buffer = Buffer.from(data);
  if (!fs.existsSync(DB_DIR)) {
    fs.mkdirSync(DB_DIR, { recursive: true });
  }
  fs.writeFileSync(DB_PATH, buffer);
}

/**
 * Create a fresh in-memory database for testing.
 * Does not touch the production database file.
 */
export async function getTestDatabase(): Promise<Database> {
  const SQL = await getSqlJs();
  const testDb = new SQL.Database();
  initializeSchema(testDb);
  return testDb;
}

/**
 * Create the users and vehicles tables if they do not exist.
 */
function initializeSchema(database: Database): void {
  database.run(`
    CREATE TABLE IF NOT EXISTS users (
      id TEXT PRIMARY KEY,
      email TEXT UNIQUE NOT NULL,
      password TEXT NOT NULL,
      role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user', 'admin')),
      createdAt TEXT NOT NULL
    )
  `);

  database.run(`
    CREATE TABLE IF NOT EXISTS vehicles (
      id TEXT PRIMARY KEY,
      make TEXT NOT NULL,
      model TEXT NOT NULL,
      year INTEGER NOT NULL,
      category TEXT NOT NULL,
      price REAL NOT NULL,
      quantity INTEGER NOT NULL DEFAULT 0,
      color TEXT,
      mileage INTEGER,
      description TEXT,
      imageUrl TEXT,
      createdAt TEXT NOT NULL,
      updatedAt TEXT NOT NULL
    )
  `);
}

/**
 * Close and reset the singleton database instance.
 */
export function closeDatabase(): void {
  if (dbInstance) {
    dbInstance.close();
    dbInstance = null;
  }
}

/**
 * Execute a query that returns rows and map results to objects.
 */
export function queryAll<T>(db: Database, sql: string, params: (string | number | null)[] = []): T[] {
  const stmt = db.prepare(sql);
  stmt.bind(params);
  const rows: T[] = [];
  while (stmt.step()) {
    rows.push(stmt.getAsObject() as unknown as T);
  }
  stmt.free();
  return rows;
}

/**
 * Execute a query that returns a single row.
 */
export function queryOne<T>(db: Database, sql: string, params: (string | number | null)[] = []): T | undefined {
  const results = queryAll<T>(db, sql, params);
  return results[0];
}

/**
 * Execute an INSERT / UPDATE / DELETE statement.
 */
export function execute(db: Database, sql: string, params: (string | number | null)[] = []): void {
  const stmt = db.prepare(sql);
  stmt.run(params);
  stmt.free();
}

import bcrypt from 'bcryptjs';
import { v4 as uuidv4 } from 'uuid';
import { Database } from 'sql.js';
import { User, RegisterBody, LoginBody, AuthPayload } from '../types';
import { queryOne, execute, persistDatabase } from '../config/database';
import { generateToken } from '../middleware/auth';

const SALT_ROUNDS = 10;

/**
 * Register a new user with hashed password.
 * Throws if the email is already taken.
 */
export async function registerUser(
  db: Database,
  body: RegisterBody
): Promise<{ user: Omit<User, 'password'>; token: string }> {
  const { email, password, role = 'user' } = body;

  // Validate input
  if (!email || !password) {
    throw new Error('Email and password are required.');
  }
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw new Error('Invalid email format.');
  }
  if (password.length < 6) {
    throw new Error('Password must be at least 6 characters.');
  }

  // Check uniqueness
  const existing = queryOne<User>(db, 'SELECT id FROM users WHERE email = ?', [email]);
  if (existing) {
    throw new Error('Email is already registered.');
  }

  const id = uuidv4();
  const hashedPassword = await bcrypt.hash(password, SALT_ROUNDS);
  const createdAt = new Date().toISOString();

  execute(db, 'INSERT INTO users (id, email, password, role, createdAt) VALUES (?, ?, ?, ?, ?)', [
    id, email, hashedPassword, role, createdAt,
  ]);
  persistDatabase(db);

  const payload: AuthPayload = { userId: id, email, role };
  const token = generateToken(payload);

  return {
    user: { id, email, role, createdAt },
    token,
  };
}

/**
 * Authenticate a user with email and password.
 * Throws if credentials are invalid.
 */
export async function loginUser(
  db: Database,
  body: LoginBody
): Promise<{ user: Omit<User, 'password'>; token: string }> {
  const { email, password } = body;

  if (!email || !password) {
    throw new Error('Email and password are required.');
  }

  const user = queryOne<User>(db, 'SELECT * FROM users WHERE email = ?', [email]);
  if (!user) {
    throw new Error('Invalid email or password.');
  }

  const passwordMatch = await bcrypt.compare(password, user.password);
  if (!passwordMatch) {
    throw new Error('Invalid email or password.');
  }

  const payload: AuthPayload = { userId: user.id, email: user.email, role: user.role };
  const token = generateToken(payload);

  return {
    user: { id: user.id, email: user.email, role: user.role, createdAt: user.createdAt },
    token,
  };
}

import { v4 as uuidv4 } from 'uuid';
import { Database } from 'sql.js';
import { Vehicle, CreateVehicleBody, UpdateVehicleBody, SearchQuery } from '../types';
import { queryAll, queryOne, execute, persistDatabase } from '../config/database';

/**
 * Create a new vehicle listing.
 */
export function createVehicle(db: Database, body: CreateVehicleBody): Vehicle {
  const { make, model, year, category, price, quantity, color, mileage, description, imageUrl } = body;

  if (!make || !model || !year || !category || price === undefined || quantity === undefined) {
    throw new Error('make, model, year, category, price, and quantity are required.');
  }
  if (price < 0) throw new Error('Price cannot be negative.');
  if (quantity < 0) throw new Error('Quantity cannot be negative.');
  if (year < 1886 || year > new Date().getFullYear() + 2) {
    throw new Error('Invalid vehicle year.');
  }

  const id = uuidv4();
  const now = new Date().toISOString();

  execute(db,
    `INSERT INTO vehicles (id, make, model, year, category, price, quantity, color, mileage, description, imageUrl, createdAt, updatedAt)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [id, make, model, year, category, price, quantity, color ?? null, mileage ?? null, description ?? null, imageUrl ?? null, now, now]
  );
  persistDatabase(db);

  return getVehicleById(db, id) as Vehicle;
}

/**
 * Get all vehicles with optional pagination.
 */
export function getAllVehicles(db: Database, page = 1, limit = 20): { vehicles: Vehicle[]; total: number; page: number; limit: number } {
  const offset = (page - 1) * limit;
  const vehicles = queryAll<Vehicle>(db, 'SELECT * FROM vehicles ORDER BY createdAt DESC LIMIT ? OFFSET ?', [limit, offset]);
  const countResult = queryOne<{ count: number }>(db, 'SELECT COUNT(*) as count FROM vehicles', []);
  const total = countResult?.count ?? 0;
  return { vehicles, total, page, limit };
}

/**
 * Get a single vehicle by ID.
 */
export function getVehicleById(db: Database, id: string): Vehicle | undefined {
  return queryOne<Vehicle>(db, 'SELECT * FROM vehicles WHERE id = ?', [id]);
}

/**
 * Search vehicles by make, model, category, or price range.
 */
export function searchVehicles(db: Database, query: SearchQuery): { vehicles: Vehicle[]; total: number } {
  const { make, model, category, minPrice, maxPrice, page = '1', limit = '20' } = query;

  const conditions: string[] = [];
  const params: (string | number | null)[] = [];

  if (make) { conditions.push('LOWER(make) LIKE ?'); params.push(`%${make.toLowerCase()}%`); }
  if (model) { conditions.push('LOWER(model) LIKE ?'); params.push(`%${model.toLowerCase()}%`); }
  if (category) { conditions.push('LOWER(category) LIKE ?'); params.push(`%${category.toLowerCase()}%`); }
  if (minPrice) { conditions.push('price >= ?'); params.push(parseFloat(minPrice)); }
  if (maxPrice) { conditions.push('price <= ?'); params.push(parseFloat(maxPrice)); }

  const where = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';
  const pageNum = parseInt(page, 10);
  const limitNum = parseInt(limit, 10);
  const offset = (pageNum - 1) * limitNum;

  const countResult = queryOne<{ count: number }>(db, `SELECT COUNT(*) as count FROM vehicles ${where}`, params);
  const total = countResult?.count ?? 0;
  const vehicles = queryAll<Vehicle>(db, `SELECT * FROM vehicles ${where} ORDER BY createdAt DESC LIMIT ? OFFSET ?`, [...params, limitNum, offset]);

  return { vehicles, total };
}

/**
 * Update a vehicle's details by ID.
 * Only updates provided fields.
 */
export function updateVehicle(db: Database, id: string, body: UpdateVehicleBody): Vehicle {
  const existing = getVehicleById(db, id);
  if (!existing) throw new Error('Vehicle not found.');

  if (body.price !== undefined && body.price < 0) throw new Error('Price cannot be negative.');
  if (body.quantity !== undefined && body.quantity < 0) throw new Error('Quantity cannot be negative.');

  const updated = { ...existing, ...body, updatedAt: new Date().toISOString() };

  execute(db,
    `UPDATE vehicles SET make=?, model=?, year=?, category=?, price=?, quantity=?, color=?, mileage=?, description=?, imageUrl=?, updatedAt=?
     WHERE id=?`,
    [updated.make, updated.model, updated.year, updated.category, updated.price, updated.quantity,
     updated.color ?? null, updated.mileage ?? null, updated.description ?? null, updated.imageUrl ?? null,
     updated.updatedAt, id]
  );
  persistDatabase(db);

  return getVehicleById(db, id) as Vehicle;
}

/**
 * Delete a vehicle by ID.
 */
export function deleteVehicle(db: Database, id: string): void {
  const existing = getVehicleById(db, id);
  if (!existing) throw new Error('Vehicle not found.');
  execute(db, 'DELETE FROM vehicles WHERE id = ?', [id]);
  persistDatabase(db);
}

/**
 * Purchase a vehicle — decrements quantity by 1.
 * Throws if out of stock.
 */
export function purchaseVehicle(db: Database, id: string): Vehicle {
  const vehicle = getVehicleById(db, id);
  if (!vehicle) throw new Error('Vehicle not found.');
  if (vehicle.quantity <= 0) throw new Error('Vehicle is out of stock.');

  execute(db, 'UPDATE vehicles SET quantity = quantity - 1, updatedAt = ? WHERE id = ?', [new Date().toISOString(), id]);
  persistDatabase(db);

  return getVehicleById(db, id) as Vehicle;
}

/**
 * Restock a vehicle — increments quantity by given amount.
 */
export function restockVehicle(db: Database, id: string, amount: number): Vehicle {
  if (!amount || amount <= 0) throw new Error('Restock amount must be a positive number.');
  const vehicle = getVehicleById(db, id);
  if (!vehicle) throw new Error('Vehicle not found.');

  execute(db, 'UPDATE vehicles SET quantity = quantity + ?, updatedAt = ? WHERE id = ?', [amount, new Date().toISOString(), id]);
  persistDatabase(db);

  return getVehicleById(db, id) as Vehicle;
}

/**
 * TDD: Auth Service Tests
 * Red-Green-Refactor cycle:
 * RED   - write failing tests first
 * GREEN - implement minimum code to pass
 * REFACTOR - clean up keeping tests green
 */
import { getTestDatabase } from '../../config/database';
import { registerUser, loginUser } from '../authService';
import { Database } from 'sql.js';

let db: Database;

beforeEach(async () => {
  db = await getTestDatabase();
});

afterEach(() => {
  db.close();
});

// ─────────────────────────────────────────────
// REGISTER
// ─────────────────────────────────────────────
describe('authService.registerUser', () => {
  it('should register a new user and return token + user data', async () => {
    const result = await registerUser(db, { email: 'alice@example.com', password: 'secret123' });

    expect(result.token).toBeDefined();
    expect(typeof result.token).toBe('string');
    expect(result.user.email).toBe('alice@example.com');
    expect(result.user.role).toBe('user');
    expect(result.user.id).toBeDefined();
    expect((result.user as any).password).toBeUndefined();
  });

  it('should register a user with admin role when specified', async () => {
    const result = await registerUser(db, { email: 'admin@example.com', password: 'admin123', role: 'admin' });

    expect(result.user.role).toBe('admin');
  });

  it('should throw if email is already taken', async () => {
    await registerUser(db, { email: 'duplicate@example.com', password: 'pass123' });

    await expect(
      registerUser(db, { email: 'duplicate@example.com', password: 'other123' })
    ).rejects.toThrow('Email is already registered.');
  });

  it('should throw if email is missing', async () => {
    await expect(
      registerUser(db, { email: '', password: 'pass123' })
    ).rejects.toThrow('Email and password are required.');
  });

  it('should throw if password is too short', async () => {
    await expect(
      registerUser(db, { email: 'user@example.com', password: '123' })
    ).rejects.toThrow('Password must be at least 6 characters.');
  });

  it('should throw if email format is invalid', async () => {
    await expect(
      registerUser(db, { email: 'not-an-email', password: 'pass123' })
    ).rejects.toThrow('Invalid email format.');
  });

  it('should hash the password (not store plain text)', async () => {
    await registerUser(db, { email: 'secure@example.com', password: 'mypassword' });

    // Read raw from DB to verify hashing
    const stmt = db.prepare('SELECT password FROM users WHERE email = ?');
    stmt.bind(['secure@example.com']);
    let stored = '';
    while (stmt.step()) {
      stored = stmt.getAsObject().password as string;
    }
    stmt.free();

    expect(stored).not.toBe('mypassword');
    expect(stored).toMatch(/^\$2[ab]\$/); // bcrypt hash pattern
  });
});

// ─────────────────────────────────────────────
// LOGIN
// ─────────────────────────────────────────────
describe('authService.loginUser', () => {
  beforeEach(async () => {
    await registerUser(db, { email: 'bob@example.com', password: 'password123' });
  });

  it('should return a token and user data for valid credentials', async () => {
    const result = await loginUser(db, { email: 'bob@example.com', password: 'password123' });

    expect(result.token).toBeDefined();
    expect(result.user.email).toBe('bob@example.com');
    expect((result.user as any).password).toBeUndefined();
  });

  it('should throw for wrong password', async () => {
    await expect(
      loginUser(db, { email: 'bob@example.com', password: 'wrongpassword' })
    ).rejects.toThrow('Invalid email or password.');
  });

  it('should throw for non-existent email', async () => {
    await expect(
      loginUser(db, { email: 'ghost@example.com', password: 'password123' })
    ).rejects.toThrow('Invalid email or password.');
  });

  it('should throw if email or password is missing', async () => {
    await expect(
      loginUser(db, { email: '', password: 'password123' })
    ).rejects.toThrow('Email and password are required.');
  });
});

/**
 * TDD: Vehicle Service Tests
 * Covers full CRUD, search, purchase, and restock logic.
 */
import { getTestDatabase } from '../../config/database';
import {
  createVehicle, getAllVehicles, getVehicleById,
  searchVehicles, updateVehicle, deleteVehicle,
  purchaseVehicle, restockVehicle,
} from '../vehicleService';
import { Database } from 'sql.js';

let db: Database;

const sampleVehicle = {
  make: 'Toyota',
  model: 'Camry',
  year: 2023,
  category: 'Sedan',
  price: 28000,
  quantity: 5,
  color: 'Silver',
};

beforeEach(async () => {
  db = await getTestDatabase();
});

afterEach(() => {
  db.close();
});

// ─────────────────────────────────────────────
// CREATE
// ─────────────────────────────────────────────
describe('vehicleService.createVehicle', () => {
  it('should create and return a vehicle with a generated ID', () => {
    const vehicle = createVehicle(db, sampleVehicle);

    expect(vehicle.id).toBeDefined();
    expect(vehicle.make).toBe('Toyota');
    expect(vehicle.model).toBe('Camry');
    expect(vehicle.year).toBe(2023);
    expect(vehicle.price).toBe(28000);
    expect(vehicle.quantity).toBe(5);
  });

  it('should throw if required fields are missing', () => {
    expect(() => createVehicle(db, { make: '', model: 'Camry', year: 2023, category: 'Sedan', price: 28000, quantity: 5 }))
      .toThrow('make, model, year, category, price, and quantity are required.');
  });

  it('should throw if price is negative', () => {
    expect(() => createVehicle(db, { ...sampleVehicle, price: -100 }))
      .toThrow('Price cannot be negative.');
  });

  it('should throw if quantity is negative', () => {
    expect(() => createVehicle(db, { ...sampleVehicle, quantity: -1 }))
      .toThrow('Quantity cannot be negative.');
  });

  it('should throw for invalid year', () => {
    expect(() => createVehicle(db, { ...sampleVehicle, year: 1800 }))
      .toThrow('Invalid vehicle year.');
  });

  it('should persist optional fields', () => {
    const vehicle = createVehicle(db, { ...sampleVehicle, description: 'Great car', mileage: 15000 });
    expect(vehicle.description).toBe('Great car');
    expect(vehicle.mileage).toBe(15000);
  });
});

// ─────────────────────────────────────────────
// READ
// ─────────────────────────────────────────────
describe('vehicleService.getAllVehicles', () => {
  it('should return an empty list when no vehicles exist', () => {
    const result = getAllVehicles(db);
    expect(result.vehicles).toHaveLength(0);
    expect(result.total).toBe(0);
  });

  it('should return all vehicles with pagination metadata', () => {
    createVehicle(db, sampleVehicle);
    createVehicle(db, { ...sampleVehicle, make: 'Honda', model: 'Civic' });

    const result = getAllVehicles(db, 1, 10);
    expect(result.vehicles).toHaveLength(2);
    expect(result.total).toBe(2);
    expect(result.page).toBe(1);
    expect(result.limit).toBe(10);
  });
});

describe('vehicleService.getVehicleById', () => {
  it('should return a vehicle by ID', () => {
    const created = createVehicle(db, sampleVehicle);
    const found = getVehicleById(db, created.id);
    expect(found).toBeDefined();
    expect(found!.id).toBe(created.id);
  });

  it('should return undefined for unknown ID', () => {
    expect(getVehicleById(db, 'non-existent-id')).toBeUndefined();
  });
});

// ─────────────────────────────────────────────
// SEARCH
// ─────────────────────────────────────────────
describe('vehicleService.searchVehicles', () => {
  beforeEach(() => {
    createVehicle(db, { make: 'Toyota', model: 'Camry', year: 2023, category: 'Sedan', price: 28000, quantity: 5 });
    createVehicle(db, { make: 'Toyota', model: 'RAV4', year: 2022, category: 'SUV', price: 35000, quantity: 3 });
    createVehicle(db, { make: 'Honda', model: 'Civic', year: 2024, category: 'Sedan', price: 24000, quantity: 10 });
    createVehicle(db, { make: 'BMW', model: 'M3', year: 2023, category: 'Sports', price: 75000, quantity: 2 });
  });

  it('should filter by make', () => {
    const result = searchVehicles(db, { make: 'Toyota' });
    expect(result.vehicles).toHaveLength(2);
    expect(result.vehicles.every(v => v.make === 'Toyota')).toBe(true);
  });

  it('should filter by model', () => {
    const result = searchVehicles(db, { model: 'Civic' });
    expect(result.vehicles).toHaveLength(1);
    expect(result.vehicles[0].model).toBe('Civic');
  });

  it('should filter by category', () => {
    const result = searchVehicles(db, { category: 'Sedan' });
    expect(result.vehicles).toHaveLength(2);
  });

  it('should filter by price range', () => {
    const result = searchVehicles(db, { minPrice: '25000', maxPrice: '40000' });
    expect(result.vehicles).toHaveLength(2); // Camry + RAV4
    result.vehicles.forEach(v => {
      expect(v.price).toBeGreaterThanOrEqual(25000);
      expect(v.price).toBeLessThanOrEqual(40000);
    });
  });

  it('should return case-insensitive results', () => {
    const result = searchVehicles(db, { make: 'toyota' });
    expect(result.vehicles).toHaveLength(2);
  });

  it('should return all vehicles with no filters', () => {
    const result = searchVehicles(db, {});
    expect(result.total).toBe(4);
  });
