@import "tailwindcss";

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=Outfit:wght@400;600;700;800&display=swap');

/* ─────────────────────────────────────────────
   Design Tokens
───────────────────────────────────────────── */
:root {
  --color-primary: #6366f1;
  --color-primary-dark: #4f46e5;
  --color-accent: #f59e0b;
  --color-success: #10b981;
  --color-danger: #ef4444;
  --color-bg: #0a0a14;
  --color-surface: #111128;
  --color-surface-2: #1a1a35;
  --color-border: rgba(99, 102, 241, 0.15);
  --color-text: #e2e8f0;
  --color-muted: #94a3b8;
  --gradient-primary: linear-gradient(135deg, #6366f1 0%, #8b5cf6 50%, #a855f7 100%);
  --gradient-card: linear-gradient(135deg, rgba(99,102,241,0.05) 0%, rgba(139,92,246,0.03) 100%);
  --shadow-glow: 0 0 40px rgba(99,102,241,0.2);
  --shadow-card: 0 4px 24px rgba(0,0,0,0.4);
}

/* ─────────────────────────────────────────────
   Base
───────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; }

body {
  margin: 0;
  font-family: 'Inter', sans-serif;
  background-color: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  overflow-x: hidden;
}

h1, h2, h3, h4 {
  font-family: 'Outfit', sans-serif;
}

/* ─────────────────────────────────────────────
   Scrollbar
───────────────────────────────────────────── */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: var(--color-surface); }
::-webkit-scrollbar-thumb { background: var(--color-primary); border-radius: 3px; }

/* ─────────────────────────────────────────────
   Animated Background
───────────────────────────────────────────── */
.bg-grid {
  background-image: 
    linear-gradient(rgba(99,102,241,0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(99,102,241,0.03) 1px, transparent 1px);
  background-size: 40px 40px;
}

/* ─────────────────────────────────────────────
   Glass Card
───────────────────────────────────────────── */
.glass-card {
  background: var(--gradient-card);
  border: 1px solid var(--color-border);
  backdrop-filter: blur(12px);
  box-shadow: var(--shadow-card);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.glass-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-glow);
  border-color: rgba(99,102,241,0.3);
}

/* ─────────────────────────────────────────────
   Buttons
───────────────────────────────────────────── */
.btn-primary {
  background: var(--gradient-primary);
  color: white;
  border: none;
  border-radius: 10px;
  font-weight: 600;
  letter-spacing: 0.02em;
  cursor: pointer;
  transition: all 0.2s ease;
  position: relative;
  overflow: hidden;
}
.btn-primary::after {
  content: '';
